<template>
  <div class="aa-root">
    <div v-if="!attachments || !attachments.length" class="aa-empty">
      No attachments were submitted with this application.
    </div>

    <div v-else class="aa-groups">
      <div v-for="group in groupedAttachments" :key="group.category" class="aa-group">
        <div class="aa-group__header">
          <v-icon size="16" color="teal darken-1">{{ group.icon }}</v-icon>
          {{ group.label }}
          <span class="aa-group__count">{{ group.items.length }}</span>
        </div>

        <div class="aa-list">
          <div
            v-for="(item, idx) in group.items"
            :key="item.sourceReference || idx"
            class="aa-item"
          >
            <v-icon size="20" :color="iconColor(item.file)" class="aa-item__icon">
              {{ iconFor(item.file) }}
            </v-icon>

            <div class="aa-item__body">
              <div class="aa-item__title">{{ item.title || "Attachment" }}</div>

              <div v-if="detailFields(item).length" class="aa-item__details">
                <span
                  v-for="field in detailFields(item)"
                  :key="field.label"
                  class="aa-item__detail"
                >
                  <span class="aa-item__detail-label">{{ field.label }}:</span>
                  {{ field.value }}
                </span>
              </div>

              <div
                v-if="item.description && item.description !== item.title"
                class="aa-item__desc"
              >
                {{ item.description }}
              </div>
              <div v-if="item.file && item.file.title" class="aa-item__filename">
                {{ item.file.title }}
              </div>
            </div>

            <div class="aa-item__actions">
              <v-btn
                v-if="item.file && item.file.data"
                small
                outlined
                color="teal darken-1"
                @click="view(item.file)"
              >
                <v-icon left small>mdi-eye-outline</v-icon>View
              </v-btn>
              <v-btn
                v-if="item.file && item.file.data"
                small
                text
                color="teal darken-1"
                @click="download(item.file)"
              >
                <v-icon left small>mdi-download-outline</v-icon>Download
              </v-btn>
              <span v-if="!item.file || !item.file.data" class="aa-item__missing">
                No file uploaded
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
const CATEGORY_META = {
  education: { label: "Education", icon: "mdi-school-outline", order: 0 },
  "additional-qualification": {
    label: "Additional Qualifications",
    icon: "mdi-certificate-outline",
    order: 1,
  },
  council: {
    label: "Council Registration",
    icon: "mdi-stamper",
    order: 2,
  },
  "national-id": {
    label: "National ID",
    icon: "mdi-card-account-details-outline",
    order: 3,
  },
  referee: { label: "Referee Letters", icon: "mdi-account-voice", order: 4 },
  other: { label: "Other", icon: "mdi-paperclip", order: 5 },
};

export default {
  name: "ApplicationAttachments",
  props: {
    // Each entry: { title, description, sourceReference, category, details, file }
    // — category/details are resolved server-side (see GET
    // /site/position/application/:id) from the application-attachments
    // extension's sourceReference, by looking up the originating
    // education/qualification/registration/referee record.
    attachments: {
      type: Array,
      default: () => [],
    },
  },
  computed: {
    groupedAttachments() {
      const byCategory = {};
      for (const item of this.attachments) {
        const key = item.category && CATEGORY_META[item.category] ? item.category : "other";
        if (!byCategory[key]) byCategory[key] = [];
        byCategory[key].push(item);
      }
      return Object.keys(byCategory)
        .map((key) => ({
          category: key,
          label: CATEGORY_META[key].label,
          icon: CATEGORY_META[key].icon,
          order: CATEGORY_META[key].order,
          items: byCategory[key],
        }))
        .sort((a, b) => a.order - b.order);
    },
  },
  methods: {
    detailFields(item) {
      const d = item.details;
      if (!d) return [];
      switch (item.category) {
        case "education":
          return [
            d.institution && { label: "Institution", value: d.institution },
            (d.qualification || d.qualificationLevel) && {
              label: "Qualification",
              value: [d.qualificationLevel, d.qualification].filter(Boolean).join(" — "),
            },
            (d.startDate || d.endDate) && {
              label: "Period",
              value: [d.startDate, d.endDate].filter(Boolean).join(" to "),
            },
          ].filter(Boolean);
        case "additional-qualification":
          return [
            d.qualification && { label: "Qualification", value: d.qualification },
            d.dateObtained && { label: "Date Obtained", value: d.dateObtained },
            d.notes && { label: "Notes", value: d.notes },
          ].filter(Boolean);
        case "council":
          return [
            d.council && { label: "Council", value: d.council },
            d.registrationNumber && {
              label: "Registration No.",
              value: d.registrationNumber,
            },
            d.registrationDate && {
              label: "Registered",
              value: d.registrationDate,
            },
            d.licenseStatus && { label: "Status", value: d.licenseStatus },
          ].filter(Boolean);
        case "national-id":
          return [d.nationalId && { label: "National ID", value: d.nationalId }].filter(
            Boolean,
          );
        case "referee":
          return [
            d.occupation && { label: "Occupation", value: d.occupation },
            d.address && { label: "Address", value: d.address },
            d.period && { label: "Known for", value: d.period },
          ].filter(Boolean);
        default:
          return [];
      }
    },
    iconFor(file) {
      if (!file || !file.contentType) return "mdi-file-outline";
      if (file.contentType.startsWith("image/")) return "mdi-file-image-outline";
      if (file.contentType === "application/pdf") return "mdi-file-pdf-box";
      return "mdi-file-outline";
    },
    iconColor(file) {
      if (!file || !file.data) return "grey lighten-1";
      return "teal darken-1";
    },
    toBlobUrl(file) {
      const byteChars = atob(file.data);
      const byteNumbers = new Array(byteChars.length);
      for (let i = 0; i < byteChars.length; i++) {
        byteNumbers[i] = byteChars.charCodeAt(i);
      }
      const byteArray = new Uint8Array(byteNumbers);
      const blob = new Blob([byteArray], {
        type: file.contentType || "application/octet-stream",
      });
      return URL.createObjectURL(blob);
    },
    view(file) {
      const url = this.toBlobUrl(file);
      window.open(url, "_blank");
    },
    download(file) {
      const url = this.toBlobUrl(file);
      const link = document.createElement("a");
      link.href = url;
      link.download = file.title || "attachment";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    },
  },
};
</script>

